const list = JSON.parse($input.first().json.data)
  .orderDataList
  .filter(item => item.paidTimeForNow > 1);

if (list.length === 0) {
  return [{ json: { _skip: true } }];
}

return list;

return $input.all().map(item => {
  if (item.json._skip) {
    return { json: { _skip: true } };
  }

  return {
    json: {
      "订单id": item.json.id,
      "shopName": $('Loop Over Items').first().json.shopName,
      "平台订单编号": item.json.platformOrderId,
      "订单编号": item.json.salesRecordNumber,
      "店铺": item.json.shopIdText,
      "国家": item.json.countryCodeCn,
      // "SKU": item.json.order_ellipsis_title,
      "付款时间": item.json.paidTime,
      "owner": $('Loop Over Items').first().json.owner, 
    }
  };
});

// 1. 获取输入数据
const rawData = $input.all().map(item => item.json);

// 2. 清洗 SKU：优先用已清洗好的 sku 字段，兼容旧的 SKU 长字符串
function cleanSku(item) {
  // ✅ 你现在输入里已有干净的 sku 字段，直接用
  if (item.sku && String(item.sku).trim()) {
    return String(item.sku).trim();
  }
  // 兼容旧结构：从 "商品编号*数量:xxx*1" 里截取
  let skuStr = item['SKU'] || '';
  if (skuStr.includes('商品编号*数量:')) {
    skuStr = skuStr.split('商品编号*数量:')[1];
  }
  return skuStr || '未知';
}

// 3. 组装行数据（新增 stockQuantity、warehousing_time）
const tableRows = rawData.map(item => ({
  order_no: item['订单编号'] || '未知',
  platform_no: item['平台订单编号'] || '未知',
  shopName: item['shopName'] || '未知',   // 分组键
  shop: item['店铺'] || '未知',            // 表格展示列
  country: item['国家'] || '未知',
  sku: cleanSku(item),
  stockQuantity: item.stockQuantity ?? '未知',      // ✅ 新增：库存数量
  warehousing_time: item.warehousing_time || '未知', // ✅ 新增：入库时间
  pay_time: item['付款时间'] || '未知',
  owner: item['owner'] || ''               // 负责人 ID（用于 @）
}));

const pushTime = $now.toFormat('yyyy-MM-dd HH:mm:ss');

// 4. 按 shopName 分组
const groups = tableRows.reduce((acc, row) => {
  const key = row.shopName || '未知';
  (acc[key] ||= []).push(row);
  return acc;
}, {});

// 5. 每个 shopName 一条消息
return Object.entries(groups).map(([shopName, rows]) => {
  // 表格行只保留 columns 里声明的字段，去掉 shopName 和 owner，避免飞书报 invalid name
  const tableData = rows.map(({ shopName, owner, ...rest }) => rest);

  // 收集该组内去重后的 owner ID（过滤空值）
  const ownerIds = [...new Set(
    rows.map(r => (r.owner || '').trim()).filter(Boolean)
  )];

  // 拼接 @ 内容；如果没有 owner，则显示提示文字
  const atContent = ownerIds.length
    ? ownerIds.map(id => `<at id=${id}></at>`).join(' ') + ' 请及时处理以下未发货订单'
    : '请及时处理以下未发货订单';

  return {
    json: {
      msg_type: "interactive",
      card: {
        config: { wide_screen_mode: true },
        header: {
          title: {
            content: `Param4 Rule1 未发货订单汇总 - ${shopName}`,
            tag: "plain_text"
          },
          template: "red"
        },
        elements: [
          {
            tag: "div",
            text: {
              tag: "lark_md",
              content: atContent
            }
          },
          {
            tag: "div",
            text: {
              tag: "lark_md",
              content: `**📊 数据统计：** 店铺组 **${shopName}** 共有 <font color='red'>**${rows.length}**</font> 条未发货订单，明细如下：`
            }
          },
          {
            tag: "table",
            page_size: 10,
            row_height: "low",
            header_style: {
              text_align: "left",
              background_style: "grey",
              bold: true
            },
            columns: [
              { name: "order_no", display_name: "订单编号", data_type: "text" },
              { name: "platform_no", display_name: "平台单号", data_type: "text" },
              { name: "shop", display_name: "店铺", data_type: "text" },
              { name: "country", display_name: "国家", data_type: "text" },
              { name: "sku", display_name: "SKU明细", data_type: "text" },
              { name: "stockQuantity", display_name: "库存数量", data_type: "text" },     // ✅ 新增列
              { name: "warehousing_time", display_name: "入库时间", data_type: "text" }, // ✅ 新增列
              { name: "pay_time", display_name: "付款时间", data_type: "text" }
            ],
            rows: tableData
          },
          { tag: "hr" },
          {
            tag: "div",
            text: {
              tag: "lark_md",
              content: `**🕒 推送时间：** <text_tag color='red'>${pushTime}</text_tag>`
            }
          },
          {
            tag: "note",
            elements: [
              {
                tag: "plain_text",
                content: "⚠️ 系统自动推送 | Param4 Rule1 规则触发"
              }
            ]
          }
        ]
      }
    }
  };
});

// 第一份：数组（每项形如 { json: {...} }）
const orders = $('清洗出所有需要的字段').all();
// 第二份：对象
const resp = $input.first().json;

const stockData = resp.stock_data || {};
const mapQ = resp.findOrderItemWarehouseQ || {};
const titleMap = resp.order_ellipsis_title || {};
const otherTitleMap = resp.order_ellipsis_other_title || {};
const htmlMap = resp.order_list_html_header || {};

// 从 title 提取所有 SKU，按商品行顺序返回数组
function extractSkus(titleStr) {
  if (!titleStr) return [];
  const marker = '商品编号*数量';
  const idx = titleStr.indexOf(marker);
  if (idx === -1) return [];
  const rest = titleStr.slice(idx + marker.length).replace(/^[:：]/, '');
  return rest
    .split(',')
    .map(part => {
      const m = part.match(/^\s*([\s\S]*?)\*\d+\s*$/);
      return m ? m[1].trim() : part.trim();
    })
    .filter(Boolean);
}

// 解析 findOrderItemWarehouseQ 的 value
function parseMapValue(val) {
  if (!val) return [];
  return val.split(";").filter(Boolean).map(seg => {
    const [orderItemId, stockId, warehouseId] = seg.split(":");
    return { orderItemId, stockId, warehouseId };
  });
}

// 从 order_list_html_header 建立 orderItemId -> 采购单号(orderId) 映射
const orderItemToPurchaseId = {};
for (const html of Object.values(htmlMap)) {
  if (!html) continue;
  for (const tr of html.split(/<\/tr>/i)) {
    if (!tr.trim()) continue;
    const oidMatch = tr.match(/[?&]orderId=(\d+)/);
    const oiMatch = tr.match(/data-orderitemid="(\d+)"/i);
    if (oidMatch && oiMatch) {
      orderItemToPurchaseId[oiMatch[1]] = oidMatch[1];
    }
  }
}

const result = orders.flatMap(order => {
  const j = order.json || {};
  const id = String(j.订单id);
  const items = parseMapValue(mapQ[id] || "");
  const skus = extractSkus(titleMap[id] || otherTitleMap[id] || "");

  // 没有映射到商品行：保留原 json 全部字段，附加字段置空
  if (items.length === 0) {
    return [{
      ...j,
      id,
      orderItemId: null,
      stockId: null,
      sku: skus[0] || "",
      stockQuantity: null,
      orderId: null
    }];
  }

  return items.map((it, i) => {
    const s = stockData[it.orderItemId] || {};
    return {
      ...j,                                              // 第一份数组所有字段
      id,
      orderItemId: it.orderItemId,                       // 第二份
      stockId: it.stockId,                               // 第二份
      sku: skus[i] ?? skus[0] ?? "",                     // 第二份（按行取）
      stockQuantity: s.stockQuantity ?? null,            // 第二份
      orderId: orderItemToPurchaseId[it.orderItemId] ?? null // 第二份：采购单号
    };
  });
});

return result;

const warehouse_arr = JSON.parse($input.first().json.data).purchaseData.map(item=>{
  return {
    "orderId": item.groupId,
    "warehousing_time": item.lastStorageTime
  }
})

const rows = $('根据订单id匹配对应的商品数据获取stockId').all().map(i => i.json);

// ============================================================
// 3. 按 orderId 合并
// ============================================================
const timeMap = new Map(
  warehouse_arr.map(w => [w.orderId, w.warehousing_time])
);

return rows.map(r => ({
  json: {
    ...r,
    warehousing_time: timeMap.get(String(r.orderId)) ?? null
  }
}));
